pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32) -> f64 {
    let mut score = bin_residual as f64 * 1.30;

    // Lookahead pairing bonus
    if bin_residual == next_item_size && next_item_size > 0 {
        score -= 60.0;
    }

    // Time-decaying penalty
    let time_decay = (total_items - step_index) as f64 / total_items as f64;
    score -= time_decay * 12.0;

    // Favoring bins with smaller residual
    if bin_residual < mean_residual {
        score += (mean_residual - bin_residual as f64).powi(2) * 1.5;
    }

    // Penalizing bins that are almost full
    if bin_capacity - bin_residual < item_size / 2 {
        score -= 30.0;
    }

    // Favoring bins with more open bins available
    score += (open_bins_count as f64 * 1.5).min(100.0);

    // Penalizing bins that are too small for the next item
    if bin_residual < next_item_size {
        score -= 25.0;
    }

    score
}
